const raw = ($json.text || '').toString().trim();
const src = $('Filter & Dedup').item.json || {};
const isSentinel = src.sentinel === true || !src.url;
if (isSentinel) {
  return { json: { isReal: false, isSentinel: true, include: false, companyName: '', anchor: '', sector: '', title: '', url: '', pubDate: '', description: '', category: '', funding: 'N/A', fundingMillions: null, summary: '', reason: 'No new articles' } };
}
const companyName = (src.companyName || '').toString();
const anchor = (src.anchor || '').toString();
const sector = (src.sector || '').toString();
const title = (src.title || '').toString();
const url = (src.url || '').toString();
const pubDate = (src.pubDate || '').toString();
const description = (src.description || '').toString();
const allowed = ['Product Launch','Partnership','Funding','Leadership Change','Research Publication','Hiring Signal','Regulatory/Legal','Other'];
function parseFundingToMillions(str) {
  if (!str) return null;
  let s = str.toString().toUpperCase().split(',').join('').split('$').join('').trim();
  let mult = 1;
  if (s.indexOf('B') !== -1) mult = 1000;
  else if (s.indexOf('M') !== -1) mult = 1;
  else if (s.indexOf('K') !== -1) mult = 0.001;
  const num = parseFloat(s);
  if (isNaN(num)) return null;
  return num * mult;
}
function grab(text, key) {
  const marker = '"' + key + '"';
  let i = text.indexOf(marker);
  if (i === -1) return '';
  i = text.indexOf(':', i);
  if (i === -1) return '';
  const q1 = text.indexOf('"', i);
  if (q1 === -1) return '';
  const q2 = text.indexOf('"', q1 + 1);
  if (q2 === -1) return '';
  return text.substring(q1 + 1, q2);
}
let category = 'Other';
let funding = 'N/A';
let summary = '';
try {
  const cleaned = raw.split('```json').join('').split('```').join('').trim();
  const parsed = JSON.parse(cleaned);
  category = (parsed.category || 'Other').toString().trim();
  funding = (parsed.funding || 'N/A').toString().trim();
  summary = (parsed.summary || '').toString().trim();
} catch (e) {
  const c = grab(raw, 'category');
  const f = grab(raw, 'funding');
  const s = grab(raw, 'summary');
  if (c) category = c.trim();
  if (f) funding = f.trim();
  if (s) summary = s.trim();
}
while (category.length && category.charAt(category.length - 1) === '.') category = category.slice(0, -1);
category = category.trim();
let canon = 'Other';
for (const a of allowed) { if (a.toLowerCase() === category.toLowerCase()) { canon = a; break; } }
category = canon;
const fundingMillions = parseFundingToMillions(funding);
const isMonetary = (category === 'Funding');
let include = false;
if (category !== 'Other') {
  if (isMonetary) { include = (fundingMillions !== null && fundingMillions >= 100); }
  else { include = true; }
}
let reason = 'Included';
if (category === 'Other') reason = 'Excluded: category Other';
else if (isMonetary && !(fundingMillions !== null && fundingMillions >= 100)) reason = 'Excluded: below $100M threshold';
return { json: { isReal: true, isSentinel: false, companyName, anchor, sector, title, url, pubDate, description, category, funding, fundingMillions, summary, include, reason } };

const NL = String.fromCharCode(10);
const items = $input.all();
const included = [];
for (const it of items) {
  const j = it.json || {};
  if (j.include === true) included.push(j);
}
let combined = '';
for (let i = 0; i < included.length; i++) {
  const a = included[i];
  combined += (i + 1) + '. Company: ' + (a.companyName || '') + NL;
  combined += 'Category: ' + (a.category || '') + NL;
  if (a.funding && a.funding !== 'N/A') combined += 'Funding/Value: ' + a.funding + NL;
  combined += 'Headline: ' + (a.title || '') + NL;
  combined += 'Summary: ' + (a.summary || '') + NL;
  combined += 'Source: ' + (a.url || '') + NL + NL;
}
const count = included.length;
const hasSignals = count > 0;
return [{ json: { count, hasSignals, combined } }];

const NL = String.fromCharCode(10);
const BS = String.fromCharCode(92);
const PARA = String.fromCharCode(1);
let text = ($json.text || '').toString();
text = text.split(BS + 'n').join(NL);
text = text.split(NL + NL).join(PARA);
text = text.split(NL).join(' ');
text = text.split(PARA).join(NL + NL);
while (text.indexOf('  ') !== -1) { text = text.split('  ').join(' '); }
text = text.trim();
const html = text.split(NL + NL).join('<br><br>');
return { json: { text, html } };
